SetColumns(0);SetQuitOnError(true);SetNthreads(1);SetMemoryLimit(5*10^9);Alarm(400);tt:=Cputime();root:="work/deg10/continuation_20261031b/M3N33/";dat:=eval Read(root cat "relative_kummer_frame.m");bps:=eval Read(root cat "relative_base_cusps.m");F2:=GF(2);R2:=PolynomialRing(F2);k<w>:=ext<F2|R2!dat[1]>;B<u>:=FunctionField(k);PK:=PolynomialRing(k);R<Y>:=PolynomialRing(B);
function DC(a)return k!(a mod 2)+k!(a div 2)*w;end function;
function DR(a)return B!(PK![DC(c):c in a[1]])/(B!(PK![DC(c):c in a[2]]));end function;
F<v>:=FunctionField(R![DR(c):c in dat[2]]);assert Genus(F) eq 21;function DF(a)return F![DR(c):c in a];end function;
O:=MaximalOrderFinite(F);OI:=MaximalOrderInfinite(F);a:=bps[1];OP:=a[2] eq 1 select O else OI;I:=ideal<OP|[DF(c):c in a[3]]>;assert IsPrime(I);P:=Place(I);dd:=-DF(dat[3][1]);m:=Valuation(dd,P);print "M333_BASE_COMPLETION_POINT_READY",Degree(P),m,Cputime(tt);C,cp:=Completion(F,P:Precision:=80);print "M333_BASE_COMPLETION_READY",Cputime(tt);uz:=cp(F!u);vz:=cp(v);dz:=cp(dd);assert Valuation(dz) eq m;print "M333_BASE_GENERATOR_SERIES_READY",Valuation(uz),Valuation(vz),Valuation(dz),Cputime(tt);
seen:=AssociativeArray();count:=0;for bf in dat[5] do for co in bf do f:=DF(co);if not IsDefined(seen,f) then seen[f]:=cp(f);count+:=1;if count mod 25 eq 0 then print "M333_BASE_FUNCTION_SERIES_PROGRESS",count,Cputime(tt);end if;end if;end for;end for;Write(root cat "base_completion_probe.txt",Sprint([*Degree(P),m,count,Cputime(tt)*]):Overwrite:=true);print "D31B_M333_BASE_COMPLETION_PROBE_COMPLETE",count,Cputime(tt);quit;
